structs.fft_complex:
struct fft_complex
{
    float real;
    float imag;
}

functions.next_reversed_n:
static inline size_t next_reversed_n(size_t reversed_n, size_t shift)
{
    reversed_n <<= shift;
    size_t count_leading_ones = _Generic(~reversed_n,
        unsigned int: __builtin_clz(~reversed_n),
        unsigned long: __builtin_clzl(~reversed_n),
        unsigned long long: __builtin_clzll(~reversed_n));
    reversed_n <<= count_leading_ones;
    reversed_n |= (size_t)1 << ((sizeof(size_t) * 8) - 1);
    reversed_n >>= (shift + count_leading_ones);
    return reversed_n;
}

functions.rader:
static inline void rader(const fft_complex_t *restrict array, fft_complex_t *restrict target, size_t logsize)
{
    size_t size = (size_t)1 << logsize;
    size_t shift = (sizeof(size_t) * 8) - logsize;
    for (size_t n = 0, reversed_n = 0; n < size; ++n)
    {
        do
        {
            target[reversed_n] = array[n];
        } while (0);
        reversed_n = next_reversed_n(reversed_n, shift);
    }
}

functions.rader_inplace:
static inline void rader_inplace(fft_complex_t *array, size_t logsize)
{
    size_t size = (size_t)1 << logsize;
    size_t shift = (sizeof(size_t) * 8) - logsize;
    for (size_t n = 1, reversed_n = size >> 1; n < size - 1; ++n)
    {
        if (n < reversed_n)
            do
            {
                fft_complex_t tmp = array[n];
                array[n] = array[reversed_n];
                array[reversed_n] = tmp;
            } while (0);
        reversed_n = next_reversed_n(reversed_n, shift);
    }
}

functions.fft_raw:
static void fft_raw(fft_complex_t *x, size_t logsize)
{
    if (__builtin_expect(!!(logsize == 0), 0))
        return;
    fft_complex_t *begin = x;
    fft_complex_t *end = begin + ((size_t)1 << logsize);
    do
    {
        fft_complex_t unit;
        do
        {
            (unit).real = cos(2 * 3.14159265358979323846 / (2));
            (unit).imag = -sin(2 * 3.14159265358979323846 / (2));
        } while (0);
        const size_t half = (2) / 2;
        for (fft_complex_t *p = (begin); p != (end); p += (2))
        {
            fft_complex_t t, u;
            do
            {
                t = p[half];
            } while (0);
            do
            {
                u = p[0];
            } while (0);
            do
            {
                (p[0]).real = (u).real + (t).real;
                (p[0]).imag = (u).imag + (t).imag;
            } while (0);
            do
            {
                (p[half]).real = (u).real - (t).real;
                (p[half]).imag = (u).imag - (t).imag;
            } while (0);
            if (half <= 1)
                continue;
            fft_complex_t root;
            do
            {
                root = unit;
            } while (0);
            do
            {
                (t).real = (root).real * (p[half + 1]).real - (root).imag * (p[half + 1]).imag;
                (t).imag = (root).real * (p[half + 1]).imag + (root).imag * (p[half + 1]).real;
            } while (0);
            do
            {
                u = p[1];
            } while (0);
            do
            {
                (p[1]).real = (u).real + (t).real;
                (p[1]).imag = (u).imag + (t).imag;
            } while (0);
            do
            {
                (p[half + 1]).real = (u).real - (t).real;
                (p[half + 1]).imag = (u).imag - (t).imag;
            } while (0);
            for (size_t i = 2, j = half + 2; i < half; ++i, ++j)
            {
                do
                {
                    float r = (root).real * (unit).real - (root).imag * (unit).imag;
                    float i = (root).real * (unit).imag + (root).imag * (unit).real;
                    (root).real = r;
                    (root).imag = i;
                } while (0);
                fft_complex_t t, u;
                do
                {
                    (t).real = (root).real * (p[j]).real - (root).imag * (p[j]).imag;
                    (t).imag = (root).real * (p[j]).imag + (root).imag * (p[j]).real;
                } while (0);
                do
                {
                    u = p[i];
                } while (0);
                do
                {
                    (p[i]).real = (u).real + (t).real;
                    (p[i]).imag = (u).imag + (t).imag;
                } while (0);
                do
                {
                    (p[j]).real = (u).real - (t).real;
                    (p[j]).imag = (u).imag - (t).imag;
                } while (0);
            }
        }
    } while (0);
    if (__builtin_expect(!!(logsize == 1), 0))
        return;
    do
    {
        fft_complex_t unit;
        do
        {
            (unit).real = cos(2 * 3.14159265358979323846 / (4));
            (unit).imag = -sin(2 * 3.14159265358979323846 / (4));
        } while (0);
        const size_t half = (4) / 2;
        for (fft_complex_t *p = (begin); p != (end); p += (4))
        {
            fft_complex_t t, u;
            do
            {
                t = p[half];
            } while (0);
            do
            {
                u = p[0];
            } while (0);
            do
            {
                (p[0]).real = (u).real + (t).real;
                (p[0]).imag = (u).imag + (t).imag;
            } while (0);
            do
            {
                (p[half]).real = (u).real - (t).real;
                (p[half]).imag = (u).imag - (t).imag;
            } while (0);
            if (half <= 1)
                continue;
            fft_complex_t root;
            do
            {
                root = unit;
            } while (0);
            do
            {
                (t).real = (root).real * (p[half + 1]).real - (root).imag * (p[half + 1]).imag;
                (t).imag = (root).real * (p[half + 1]).imag + (root).imag * (p[half + 1]).real;
            } while (0);
            do
            {
