            } while (0);
            do
            {
                (p[1]).real = (u).real + (t).real;
                (p[1]).imag = (u).imag + (t).imag;
            } while (0);
            do
            {
                (p[half + 1]).real = (u).real - (t).real;
                (p[half + 1]).imag = (u).imag - (t).imag;
            } while (0);
            for (size_t i = 2, j = half + 2; i < half; ++i, ++j)
            {
                do
                {
