                } while (0);
            }
        }
    } while (0);
    if (__builtin_expect(!!(logsize == 2), 0))
        return;
    for (size_t step = 8; step <= (size_t)1 << logsize; step *= 2)
        do
        {
            fft_complex_t unit;
            do
            {
                (unit).real = cos(2 * 3.14159265358979323846 / (step));
                (unit).imag = -sin(2 * 3.14159265358979323846 / (step));
            } while (0);
            const size_t half = (step) / 2;
            for (fft_complex_t *p = (begin); p != (end); p += (step))
            {
                fft_complex_t t, u;
                do
                {
