functions.fft:
void fft(const fft_complex_t *restrict x, fft_complex_t *restrict X, size_t logsize)
{
    rader(x, X, logsize);
    fft_raw(X, logsize);
}

functions.fft_inplace:
void fft_inplace(fft_complex_t *x, size_t logsize)
{
    rader_inplace(x, logsize);
    fft_raw(x, logsize);
}
